"""エネルギー2：音による現象／力による現象（ワーク p100〜121）"""
from fractions import Fraction as F
from kbank import T, C, SEQ, N, S, R
from sci import unit
from matter1 import fs

def oto():
    u = unit('oto', '音の伝わり方と音の大小・高低', '音による現象', {100, 101, 102, 103},
             '2026-10-05 Claude作成。理科ワークp100〜101（教科書チェック 音の伝わり方①②・音の大小と高低①・実験4・まとめ対話）・p102基本①②と○×①〜④・p103力だめし①②を写真で確認して作成。音の速さの計算は、ワークにある「空気中を音が伝わる速さを340 m/s」の値を使い、数値を変えて作った。')
    q = u.q
    q(100, '①(1)', '振動', '音の出ているスピーカーの上に発泡ポリスチレン球を置くとはずむ。これは、スピーカーの表面がどうなっているからか。', R((1, ['振動', 'しんどう', 'ふるえ', '震え'])), 'ワークp100①(1)：スピーカーの表面が振動しているから。', example='振動しているから。')
    q(100, '①(2)', '音源', '音を発生しているものを何というか。', T('音源', 'おんげん', '発音体', '音源（発音体）'), 'ワークp100①(2)・p102①(3)：音源（発音体）。', near=['振動'])
    q(100, '①(3)', '音の伝わり方', '同じ高さの音を出す音さA、Bを並べて、音さAをたたくと、音さBはどうなるか。', R((1, ['鳴', 'なる', 'なり', 'なっ', '音が出', '振動'])), 'ワークp100①(3)・p102①(1)：音さBも鳴りはじめる（振動し、鳴りはじめる）。', example='鳴りはじめる。')
    q(100, '①(4)', '音の伝わり方', '音さAをたたいて音さBが鳴っているとき、音さBにふれると、音さBはどうなっているか。', R((1, ['振動', 'しんどう', 'ふるえ', '震え'])), 'ワークp100①(4)：音さBは振動している。', example='振動している。')
    q(102, '①(1)', '音の伝わり方', '音さAをたたいたとき、音さBはどうなるか。次から選ぼう。\nア 振動し、鳴りはじめる　イ 振動せず、鳴りはじめる　ウ 振動せず、鳴らない', T('ア'), 'ワークp102①(1)：ア。', near=['イ'])
    q(100, '①(5)', '真空と音', '容器内の空気をぬいていくと、ブザーの音の大きさはどうなるか。', T('小さくなる', 'ちいさくなる', '小さくなっていく'), 'ワークp100①(5)・p102①(2)：イ 小さくなる。', near=['大きくなる', '変わらない'])
    q(100, '①(6)', '音を伝えるもの', '音さとブザーの実験から、音を伝えているものは何だといえるか。', T('空気', 'くうき'), 'ワークp100①(6)・p102①(4)：空気。', near=['水'])
    q(102, 'ヒント', '音の伝わり方', '音は、まわりのものをどうさせることで伝わっていくか。', R((1, ['振動', 'しんどう'])), 'ワークp102ヒント(4)：音は、まわりのものを振動させることで伝わっていきます。', example='振動させることで伝わる。')
    q(100, '①(7)', '波', '音さをつけた水面に波紋が広がっていくとき、水面に浮かべた発泡ポリスチレン球はどうなるか。次から選ぼう。\nア 上下に振動しながら移動する　イ 上下に振動するだけで移動しない', T('イ'), 'ワークp100①(7)：イ。', near=['ア'])
    q(100, '①(8)', '波', '振動が次々と伝わる現象を何というか。', T('波', 'なみ'), 'ワークp100①(8)・p103①(1)：波。', near=['振動'])
    q(100, '①(9)', '音が聞こえるしくみ', '音が聞こえるのは、空気の振動が耳の中にある何を振動させるからか。', T('鼓膜', 'こまく'), 'ワークp100①(9)：鼓膜。')
    q(100, '①(10)①', '音を伝えるもの', '音は、水などの液体の中を伝わるか。', T('伝わる', 'つたわる', '伝わります'), 'ワークp100①(10)①：伝わる。', near=['伝わらない'])
    q(100, '①(10)②', '音を伝えるもの', '音は、糸や金属などの固体の中を伝わるか。', T('伝わる', 'つたわる', '伝わります'), 'ワークp100①(10)②：伝わる。', near=['伝わらない'])
    q(100, '②(1)', '音の速さ', '打ち上げ花火が見えてから音が聞こえるまでに、少し時間がかかるのはなぜか。', R((1, ['音']), (1, ['光']), (1, ['おそ', '遅', '速さ', 'はやさ'])), 'ワークp100②(1)キーワード「速さ」・p102○×①：音の伝わる速さは、光の速さに比べておそいから。', example='音の伝わる速さが光の速さよりおそいから。')
    q(102, '○×①', '音の速さ', '「音の伝わる速さは、光の速さに比べて速い。」この文の誤りを直すと、「速い」は何になるか。', T('おそい', '遅い'), 'ワークp102○×①：おそい。', near=['速い'])
    q(100, '②(2)', '音の速さ', '空気中を伝わる音の速さは、約何m/sか（ワークの力だめしで使う値）。', N(340, ['m/s', 'メートル毎秒']), 'ワークp103①：空気中を音が伝わる速さを340 m/sとする（ポイント：m/sは1秒間あたりに進む距離を表す単位）。', near=['34', '3400'])
    q(100, 'ポイント', '音の速さ', 'm/sという単位は、何を表す単位か。', R((1, ['1秒', '一秒', '１秒']), (1, ['距離', 'きょり', '進む'])), 'ワークp100ポイント：m/sは1秒間あたりに進む距離を表す単位です。', example='1秒間あたりに進む距離')
    for t in (3, 2, 5, 4, '1.5', '3.8', '0.5'):
        d = F(340) * F(str(t))
        q(100 if t == 3 else 103, '②(3)' if t == 3 else '①(2)', '音の速さの計算', f'打ち上げ花火が見えてから、音が聞こえるまでの時間が{t}秒だった。花火までの距離は約何mか。音の速さを340 m/sとする。', N(fs(d), ['m', 'メートル']), f'距離＝速さ×時間＝340×{t}＝{fs(d)} m（ヒント：花火の音は、1秒間に340 m伝わる）。', near=[fs(F(340) / F(str(t)))] if (F(340) / F(str(t))).denominator in (1, 2, 4, 5, 10) else [])
    for dist in (680, 1020, 1700, 510, 85):
        tt = F(dist, 340)
        q(103, '①(3)', '音の速さの計算', f'雷の光が見えてから、雷の音が聞こえるまでの時間を考える。雷までの距離が{dist} mのとき、音が聞こえるまで何秒かかるか。音の速さを340 m/sとする。', N(fs(tt), ['秒', 's']), f'時間＝距離÷速さ＝{dist}÷340＝{fs(tt)}秒（光はほぼ一瞬で届く）。', near=[fs(F(340, dist))] if F(340, dist).denominator in (1, 2, 4, 5, 10) else [])
    q(103, '①(3)', '音の速さの計算', '花火から明さんまでの距離より、花火から治さんまでの距離が510 m長い。治さんが花火を見てから花火の音を聞くまでの時間は、明さん（3.8秒）より何秒長いか。音の速さを340 m/sとする。', N('1.5', ['秒', 's']), 'ワークp103①(3)：510÷340＝1.5秒長い。治さんは3.8＋1.5＝5.3秒。', near=['5.3'])
    q(103, '①(3)', '音の速さの計算', '同じ問題で、治さんが花火を見てから花火の音を聞くまでの時間は何秒か（明さんは3.8秒）。', N('5.3', ['秒', 's']), 'ワークp103①(3)：510÷340＝1.5秒、3.8＋1.5＝5.3秒。', near=['1.5'])
    # 音の大小と高低
    q(101, '①(1)', '音の大きさ', 'モノコードで、弦を強くはじくほど、音はどうなるか。', T('大きくなる', 'おおきくなる', '大きい音になる'), 'ワークp101①(1)：大きくなる。', near=['高くなる'])
    q(101, '①(2)', '音の高さ', 'モノコードで、弦の長さを短くすると、音はどうなるか。', T('高くなる', 'たかくなる', '高い音になる'), 'ワークp101①(2)：高くなる。', near=['低くなる', '大きくなる'])
    q(101, '①(3)', '音の高さ', 'モノコードで、弦を強くはると、音はどうなるか。', T('高くなる', 'たかくなる', '高い音になる'), 'ワークp101①(3)・p102○×③：高くなる（弦が振動する回数が多くなる）。', near=['低くなる'])
    q(101, '①(4)', '音の高さ', 'モノコードで、弦の太さを細いものにすると、音はどうなるか。', T('高くなる', 'たかくなる', '高い音になる'), 'ワークp101①(4)：高くなる。', near=['低くなる'])
    q(102, '○×②', '音の高さ', '「モノコードのことじを動かして、はじく弦の長さを長くすると、高い音が出る。」この文の誤りを直すと、「高い」は何になるか。', T('低い', 'ひくい'), 'ワークp102○×②：低い。', near=['高い'])
    q(102, '②(1)②', '音の高さ', 'モノコードの弦のはりの強さを弱くしてはじくと、音はどうなるか。', T('低くなる', 'ひくくなる', '低い音になる'), 'ワークp102②(1)②：低くなる。', near=['高くなる'])
    q(102, '②(1)③', '音の高さ', 'モノコードの弦の長さを短くしてはじくと、音はどうなるか。', T('高くなる', 'たかくなる'), 'ワークp102②(1)③：高くなる。', near=['低くなる'])
    q(103, '②(2)①', '音の大きさ', 'モノコードの弦をはじく強さを弱くすると、音はどうなるか。', T('小さくなる', 'ちいさくなる', '小さい音になる'), 'ワークp103②(2)①：小さくなる。', near=['低くなる'])
    q(103, '②(2)②', '音の高さ', 'モノコードの弦のはり方を強くすると、音はどうなるか。', T('高くなる', 'たかくなる'), 'ワークp103②(2)②：高くなる。', near=['大きくなる'])
    q(103, '②(5)', '音の高さ', 'ギターの6本の弦は太さが異なる。弦の太さが細くなるほど、音はどうなるか。', T('高くなる', 'たかくなる', '高い音になる'), 'ワークp103②(5)・p101①(4)：高くなる。', near=['低くなる'])
    q(101, '①(5)', '振幅', '弦の振動の振れ幅を何というか。', T('振幅', 'しんぷく'), 'ワークp101①(5)・p102○×④：振幅。', near=['振動数'])
    q(101, '①(6)', '振幅', '振幅が大きいほど、音はどうなるか。次から選ぼう。\nア 大きくなる　イ 小さくなる　ウ 高くなる　エ 低くなる', T('ア'), 'ワークp101①(6)：ア 大きくなる。', near=['ウ'])
    q(101, '①(7)', '振動数', '弦が1秒間に振動する回数を何というか。', T('振動数', 'しんどうすう'), 'ワークp101①(7)・p103ヒント：振動数。', near=['振幅'])
    q(101, '①(8)', 'ヘルツ', '振動数は何という単位で表すか。', T('ヘルツ', 'Hz', 'へるつ', 'ヘルツ（Hz）'), 'ワークp101①(8)・p102②(4)：ヘルツ（Hz）。', near=['m/s'])
    q(101, '①(9)', '振動数', '振動数が多いほど、音はどうなるか。次から選ぼう。\nア 大きくなる　イ 小さくなる　ウ 高くなる　エ 低くなる', T('ウ'), 'ワークp101①(9)：ウ 高くなる。', near=['ア'])
    q(102, '○×③', '振動数', 'モノコードの弦のはりを強くするほど、弦が振動する回数はどうなるか。', T('多くなる', 'おおくなる', 'ふえる', '多い'), 'ワークp102○×③：○（多くなる）。', near=['少なくなる'])
    q(102, '②(3)', '音の大きさと波形', 'オシロスコープの波形AとBで、波の上下の振れ幅がAのほうが大きかった。音が大きいのはどちらか。', T('A'), 'ワークp102②(3)・ヒント：上下方向は振動の振れ幅を表す。振幅が大きいAのほうが音が大きい。', near=['B'])
    q(102, 'ヒント', '波形の見方', '音の波形の左右方向（横軸）と上下方向（縦軸）は、それぞれ何を表しているか。', R((1, ['時間', 'じかん']), (1, ['振れ幅', 'ふれはば', '振幅', 'しんぷく'])), 'ワークp102ヒント(2)：音の波形の左右方向は時間、上下方向は振動の振れ幅を表している。', example='左右は時間、上下は振動の振れ幅')
    q(101, '①(10)', '波形の見方', '同じ時間の範囲で、波の数が多い波形と少ない波形では、音が高いのはどちらか。', T('波の数が多い波形', '多い波形', '多いほう', '波の数が多いほう', '多い方'), 'ワークp101①(10)②：振動数が多い（波の数が多い）ほど音は高い。', near=['少ない波形'])
    q(101, '①(10)', '波形の見方', '同じ時間の範囲で、波の高さ（振幅）が小さい波形の音は、大きい音か、小さい音か。', T('小さい音', '小さい', 'ちいさい'), 'ワークp101①(10)①：振幅が小さいほど音は小さい。', near=['大きい音'])
    q(103, '②(4)', '波形の見方', 'モノコードのはじく部分を長くして同じ強さで弦をはじいたとき、波形は図1と比べてどうなるか。', R((1, ['波の数', '振動数', '山の数']), (1, ['少な', 'へる', 'へっ', '減'])), 'ワークp103②(3)(4)：弦が長いと音が低くなり、振動数が少なくなる（波の数が少なくなる）。', example='波の数（振動数）が少なくなる。')
    # 振動数の計算（まとめ対話：1目盛り0.001秒、1回の振動に5目盛り→200 Hz）
    for div, per in [(5, '0.001'), (4, '0.001'), (2, '0.002'), (5, '0.002'), (8, '0.001'), (10, '0.0005')]:
        t1 = F(div) * F(per)
        hz = 1 / t1
        q(101, 'まとめ', '振動数の計算', f'オシロスコープの波形で、1回の振動に{div}目盛り分の時間がかかっていた。横軸の1目盛りが{per}秒のとき、この音の振動数は何Hzか。', N(fs(hz), ['Hz', 'ヘルツ']), f'1回の振動にかかる時間は{per}×{div}＝{fs(t1)}秒。振動数は1秒間に振動する回数なので、1÷{fs(t1)}＝{fs(hz)} Hz（ワークp101まとめ対話）。', near=[fs(t1)])
    q(103, '②(1)', '振動数の計算', 'モノコードの音の波形で、横軸の1目盛りが0.002秒、1回の振動に4目盛り分かかっていた。振動数は何Hzか。', N(125, ['Hz', 'ヘルツ']), 'ワークp103②(1)：1回の振動は0.002×4＝0.008秒。1÷0.008＝125 Hz。', near=['0.008', '500'])
    q(101, 'まとめ', '振動数の計算', 'ある音さは1秒間に440回振動する。この音さの振動数は何Hzか。', N(440, ['Hz', 'ヘルツ']), 'ワークp101①(7)(8)：振動数は1秒間に振動する回数。440回→440 Hz。', near=['0.44'])
    q(101, 'まとめ', '振動数の計算', '振動数が500 Hzの音では、1回の振動にかかる時間は何秒か。', N('0.002', ['秒', 's']), '振動数は1秒間に振動する回数なので、1÷500＝0.002秒（ワークp101まとめ対話の逆）。', near=['500', '0.02'])
    q(100, '①(5)', '真空と音', '空気をぬいた容器の中でブザーを鳴らすと、音が小さくなるのはなぜか。', R((1, ['空気', 'くうき']), (1, ['伝え', 'つたえ', '振動', '少な', 'へる', 'へっ', 'ない'])), 'ワークp100①(5)(6)：音を伝える空気が少なくなるから。', example='音を伝える空気が少なくなるから。')
    q(100, '①(1)', '振動', '音を出しているものは、どうなっているといえるか。', R((1, ['振動', 'しんどう', 'ふるえ'])), 'ワークp100①(1)(4)・p102ヒント：音を出しているもの（音源）は振動している。', example='振動している。')
    q(101, '①(10)', '音の大きさと高さ', '弦を強くはじくと振幅と振動数のどちらが大きくなるか。', T('振幅', 'しんぷく'), 'ワークp101①(1)(6)：弦を強くはじくと音が大きくなる→振幅が大きくなる。', near=['振動数'])
    q(101, '①(10)', '音の大きさと高さ', '弦の長さを短くすると、振幅と振動数のどちらが多く（大きく）なるか。', T('振動数', 'しんどうすう'), 'ワークp101①(2)(9)：弦を短くすると音が高くなる→振動数が多くなる。', near=['振幅'])
    q(103, '②(2)', '音の大きさと高さ', 'モノコードの弦の長さとはりの強さを変えずに、はじく強さだけを変えると、音の何が変わるか。大きさと高さから選ぼう。', T('大きさ', 'おおきさ', '音の大きさ'), 'ワークp101①(1)・p103②(2)①：はじく強さは音の大きさ（振幅）に関係する。', near=['高さ'])
    q(100, '②(2)', '音の速さ', '音の速さと光の速さでは、どちらが速いか。', T('光の速さ', '光', 'ひかり'), 'ワークp100②(1)・p102○×①：音の伝わる速さは光の速さに比べておそい。', near=['音の速さ'])
    q(102, '②(2)', '振幅', 'オシロスコープの波形で、振幅を示しているのは、波の山から谷までの半分の高さ（波の中心から山の頂点まで）か、波1つ分の横の長さか。', T('波の中心から山の頂点まで', '中心から山の頂点まで', '中心から山まで', '高さ', '前者'), 'ワークp102②(2)：振幅は振動の振れ幅（波の中心から山の頂点までの高さ）。ヒント：上下方向は振動の振れ幅を表す。', near=['波1つ分の横の長さ'])
    q(100, '①(8)', '波', '音さをつけた水面に広がる波紋のように、振動が次々と伝わるとき、伝わっているのは物体そのものか、振動か。', T('振動', 'しんどう'), 'ワークp100①(7)(8)：発泡ポリスチレン球は上下に振動するだけで移動しない。伝わるのは振動（波）。', near=['物体そのもの'])
    q(101, '実験4', '実験4', '実験4で、弦をはじいて出る音の波形を調べるのに使う装置は何か。', T('オシロスコープ', 'おしろすこーぷ'), 'ワークp101実験4②：弦をはじいてオシロスコープで音の波形を調べる。')
    return u
